# Regenerates src/sql.ts from migrations/0001_init.sql and seed.sql. Run: python3 scripts/make-sql.py
import re, json

def stmts(path):
    # remove comments first (a comment may contain a semicolon), then split into statements
    lines = [re.sub(r'\s*--.*$', '', l) for l in open(path).read().split('\n')]
    text = '\n'.join(l for l in lines if l.strip())
    return [p.strip() for p in text.split(';') if p.strip()]

js = lambda L: '[\n' + ',\n'.join('  ' + json.dumps(x, ensure_ascii=False) for x in L) + '\n]'
open('src/sql.ts', 'w').write(
    "// Generated by scripts/make-sql.py from migrations/0001_init.sql and seed.sql. Do not edit by hand.\n"
    "export const SCHEMA_STATEMENTS: string[] = " + js(stmts('migrations/0001_init.sql')) + ";\n\n"
    "export const SEED_STATEMENTS: string[] = " + js(stmts('seed.sql')) + ";\n")
